/**
 * articleToc.js — "On this page" panel for article pages.
 *
 * Builds a table of contents from the h2/h3 ids generated by the Markdown
 * `toc` extension, adds hover anchor links to headings, and highlights the
 * section currently in view while scrolling.
 *
 * Plain script (no modules) — loaded with `defer` from article_template.html.
 */
(function () {
  'use strict';

  var article = document.querySelector('.article-prose');
  var tocList = document.getElementById('article-toc-list');
  var tocAside = document.querySelector('.article-toc');
  if (!article || !tocList || !tocAside) return;

  // Panel lists top-level sections only; anchor links cover h2 and h3.
  var headings = Array.prototype.slice.call(article.querySelectorAll('h2[id]'));
  var anchorTargets = Array.prototype.slice.call(
    article.querySelectorAll('h2[id], h3[id]')
  );

  // A panel with fewer than 3 entries is noise — hide it entirely.
  if (headings.length < 3) {
    tocAside.hidden = true;
    return;
  }

  /* --- Build the list ---------------------------------------------------- */
  var linkById = {};
  var fragment = document.createDocumentFragment();

  headings.forEach(function (heading) {
    var item = document.createElement('li');
    item.className =
      'article-toc__item article-toc__item--' + heading.tagName.toLowerCase();

    var link = document.createElement('a');
    link.href = '#' + heading.id;
    link.textContent = heading.textContent;

    item.appendChild(link);
    fragment.appendChild(item);
    linkById[heading.id] = link;
  });

  tocList.appendChild(fragment);

  /* --- Hover anchor links on headings ------------------------------------ */
  anchorTargets.forEach(function (heading) {
    var anchor = document.createElement('a');
    anchor.className = 'heading-anchor';
    anchor.href = '#' + heading.id;
    anchor.textContent = '¶';
    anchor.setAttribute('aria-label', 'Link to this section');
    heading.appendChild(anchor);
  });

  /* --- Scroll spy --------------------------------------------------------- */
  var activeLink = null;

  function setActive(id) {
    var link = linkById[id];
    if (link === activeLink) return;
    if (activeLink) activeLink.classList.remove('active');
    link.classList.add('active');
    activeLink = link;
  }

  function onScroll() {
    // The heading owning the reading position: last one above the fold line.
    var fold = window.scrollY + 120;
    var current = headings[0];
    for (var i = 0; i < headings.length; i++) {
      if (headings[i].offsetTop <= fold) current = headings[i];
      else break;
    }
    setActive(current.id);
  }

  var ticking = false;
  function onScrollThrottled() {
    if (ticking) return;
    ticking = true;
    setTimeout(function () {
      onScroll();
      ticking = false;
    }, 80);
  }

  document.addEventListener('scroll', onScrollThrottled, { passive: true });
  window.addEventListener('resize', onScrollThrottled, { passive: true });
  onScroll();
})();
